         if (now - lastBack < 1500) {
             super.onBackPressed();
             return;
         }
         lastBack = now;
         setPanel(!controlsExpanded);
         Toast.makeText(this, controlsExpanded
                 ? "Панель показана. Двойное «Назад» — выход"
