// a generated address and prints that, while the panel opened the reserved one
// unconditionally and served whatever else was there - a 404, i.e. a blank
// page with no explanation. Everything now comes from session.json.
let LIVE = null;
let LAST_RUNS = [];

let previewOpen = false;
let previewTab = 'screen';   // screen | term

function renderPreview() {
  const box = $('preview');
  const card = $('screen-card');
  if (!box || !card) return;

  // VNC desks are gone; the only embeddable screen left is a hub launcher root.
  const liveSlot = (LIVE && LIVE._slot) || '';
  const isHubLive = liveSlot.startsWith('hub') || (LIVE && (LIVE.hubUrl || /npm-hub/i.test(LIVE.kind || '')));
  const screen = isHubLive ? (LIVE.hubUrl || LIVE.terminal || LIVE.url || null) : null;
  const term = LIVE && LIVE.terminal ? LIVE.terminal : null;
  const agent = null; // never embed the chat SPA in a 200px preview — it janks the WebView

  // Windows RDP has nothing embeddable: it is not HTTP. Saying so beats an
  // empty black box that looks broken.
  if (!screen && !term && !agent) {
    if (LIVE && LIVE.rdpHost) {
      card.style.display = '';
      box.innerHTML = '<span class="note">Windows по RDP — встроить в браузер нельзя. ' +
        'Адрес, логин и пароль ниже; открывайте в Microsoft Remote Desktop.</span>';
    } else {
      card.style.display = 'none';
    }
    previewOpen = false;
    return;
  }

  card.style.display = '';
  if (previewTab === 'term' && !term) previewTab = 'screen';
  const url0 = previewTab === 'term' ? term : (screen || agent);
  // Session rows never carry ?zt= (gate tokens live only in this browser's
  // localStorage); without the wrap the frame shows a bare 401 instead.
  const url = (url0 && isHubLive) ? hubUrlWithToken(url0, liveSlot) : url0;
  const ztMissing = isHubLive && url0 && !(liveSlot && HUB_TOKENS[liveSlot]);
  const ztHint = ztMissing
