                     String st = run.optString("status");
                     boolean active = st.equals("queued") || st.equals("in_progress");
                     // Match by workflow path so it works for any target, not a name.
                     boolean mine = run.optString("path").endsWith("/" + workflow());
                     if (active && mine) {
