     private void pollUntilLive() {
         new Thread(() -> {
             String prev = liveUrl;
             for (int i = 0; i < 40; i++) {
                 try { Thread.sleep(10000); } catch (InterruptedException e) { return; }
                 JSONObject s = readSession();
                 String url = urlOf(s);
